import pyomo.environ as pyo

DATA = {
    "requirements": {1: 1500, 2: 1000, 3: 2000, 4: 1200},
    "fees": {1: 28, 2: 45, 3: 60, 4: 73},
    "months": [1, 2, 3, 4],
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.Months = pyo.Set(initialize=d["months"])
    pairs = [(s, u) for s in d["months"] for u in d["months"] if s <= u]
    model.Contracts = pyo.Set(initialize=pairs, dimen=2)

    # Decision variables: area rented under a contract starting month s, ending month u
    model.x = pyo.Var(model.Contracts, within=pyo.NonNegativeReals)

    # Objective: minimize total rental fee
    def obj_rule(m):
        return sum(d["fees"][u - s + 1] * m.x[s, u] for (s, u) in m.Contracts)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: coverage requirement for each month
    def coverage_rule(m, t):
        return sum(
            m.x[s, u] for (s, u) in m.Contracts if s <= t <= u
        ) >= d["requirements"][t]
    model.coverage = pyo.Constraint(model.Months, rule=coverage_rule)

    return model


if __name__ == "__main__":
    model = build_model()
    model.pprint()
